\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Climate Science Color Theme (Cool-to-Warm) ──
% Primary: deep ocean blue | Secondary: teal | Accent: warming amber
\definecolor{primary}{HTML}{1E3A5F}      % deep ocean blue (title bar)
\definecolor{secondary}{HTML}{0D7377}    % teal (section headers)
\definecolor{accent}{HTML}{C2410C}       % warming red-amber (highlights)
\definecolor{accent2}{HTML}{EA580C}      % orange (secondary accent)
\definecolor{bgposter}{HTML}{F0F7FA}      % cool blue-grey background
\definecolor{redbg}{HTML}{FEF2F2}         % warm red tint (for accent cards)
\definecolor{bluebg}{HTML}{EFF6FF}       % cool blue tint
\definecolor{darkbg}{HTML}{F5F0EB}       % warm cream (neutral cards)
\definecolor{darktitlebg}{HTML}{E8F0F5}   % dark card title bar
\definecolor{redtitlebg}{HTML}{FEF2F2}    % red title bar
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FEF3C7}
\definecolor{keyhighlight}{HTML}{FEE2E2}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=accent!15!white,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=keyhighlight,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════════
% TITLE BAR (spans all 3 columns, rows 1-4)
% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries 300 Years of Sclerosponge Thermometry}\\[10pt]
  {\fontsize{52}{62}\selectfont Global Warming Has Exceeded 1.5 \textdegree C}\\[10pt]
  {\fontsize{32}{40}\selectfont\color{white!80}AGU / Nature Climate Change Symposium 2024}
}

% ══════════════════════════════════════════════════════
% STATS BANNER (spans all 3 columns, rows 5-6)
% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={2pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary}\textasciitilde300}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} years of proxy data}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textgray} back to \textasciitilde1700 CE}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!50}{keyhighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent}+0.5\textdegree C}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} hidden warming}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textgray} before 1850--1900}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary}\textgreater1.5\textdegree C}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} already exceeded}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textgray} true pre-industrial baseline}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════
% ROW A (rows 6-11): Timeline chart + Background + Key Finding
% ══════════════════════════════════════════════════════

% ── 300-Year Temperature Timeline (HERO FIGURE - spanning key area) ──
\posterbox[
  enhanced, colback=white, boxrule=1pt, arc=0pt,
  borderline={0.5pt}{0pt}{primary!40},
  left=12pt, right=12pt, top=8pt, bottom=6pt,
  valign=top, drop shadow={opacity=0.12}
]{name=timeline, column=1, span=3, between=row6 and row11}{
  \fontsize{32}{40}\selectfont\bfseries\color{primary} 300-Year Temperature Reconstruction}\\[6pt]
  \vspace{2mm}
  % Timeline visualization using TikZ
  \begin{tikzpicture}[x=0.95\linewidth, y=0.45\textheight, scale=1]
    % Background gradient (cool to warm)
    \fill[top color=secondary!20!white, bottom color=accent!20!white] (0,0) rectangle (1,1);

    % Y-axis labels and threshold line
    \draw[thick, primary] (-0.05,0) -- (-0.05,1);
    \node[rotate=90, anchor=center] at (-0.12,0.5) {\fontsize{22}{28}\selectfont Temperature Anomaly (\textdegree C)};
    % 0 line
    \draw[gray, thin] (0,0.5) -- (1,0.5);
    \node at (-0.02,0.5) [left] {\fontsize{20}{26}\selectfont 0};
    % +1.0 line
    \draw[gray, thin, dashed] (0,0.75) -- (1,0.75);
    \node at (-0.02,0.75) [left] {\fontsize{20}{26}\selectfont +1.0};
    % 1.5°C threshold (key line)
    \draw[ultra thick, accent] (0,0.82) -- (1,0.82);
    \node at (1.02,0.82) [right] {\fontsize{22}{28}\selectfont\bfseries\color{accent} 1.5\textdegree C threshold};

    % Time axis (bottom)
    \draw[thick, primary] (0,-0.08) -- (1,-0.08);
    \foreach \x/\year in {0/1700, 0.15/1750, 0.3/1800, 0.45/1850, 0.6/1900, 0.75/1950, 0.9/2000, 1/2020} {
      \draw (\x,-0.06) -- (\x,-0.10);
      \node at (\x,-0.12) [below, anchor=north] {\fontsize{18}{24}\selectfont\year};
    }

    % Stylized temperature curve (approximating the sclerosponge data)
    % Pre-industrial period (1700-1790): stable near 0
    \draw[very thick, secondary] (0,0.48) .. controls (0.05,0.49) and (0.1,0.48) .. (0.15,0.49);
    % Early warming (1790-1850): slight rise
    \draw[very thick, secondary] (0.15,0.49) .. controls (0.22,0.50) and (0.28,0.51) .. (0.35,0.52);
    % 1850-1900: continued rise (already +0.3 to +0.5)
    \draw[very thick, secondary!60!accent] (0.35,0.52) .. controls (0.42,0.55) and (0.48,0.58) .. (0.55,0.60);
    % 1900-1960: gradual
    \draw[very thick, accent!70!secondary] (0.55,0.60) .. controls (0.62,0.63) and (0.68,0.65) .. (0.72,0.68);
    % 1960-2000: acceleration
    \draw[very thick, accent!60!primary] (0.72,0.68) .. controls (0.78,0.72) and (0.83,0.76) .. (0.87,0.78);
    % 2000-present: crossing 1.5°C
    \draw[very thick, accent] (0.87,0.78) .. controls (0.92,0.80) and (0.96,0.82) .. (1,0.85);

    % Key milestone annotations
    \node[anchor=south west] at (0.35,0.62) {\fontsize{16}{22}\selectfont\color{accent!80!textdark} 1850: +0.5\textdegree C hidden};
    \draw[accent, ->] (0.38,0.65) to [bend left=15] (0.32,0.55);

    \node[anchor=south east] at (0.92,0.85) {\fontsize{18}{24}\selectfont\bfseries\color{accent} 2020s: $>1.5$\textdegree C};
    \draw[accent, ->] (0.88,0.84) to [bend right=10] (0.93,0.88);

    % "True pre-industrial baseline" arrow
    \draw[primary, <->] (0.02,0.35) -- (0.13,0.35);
    \node at (0.075,0.28) {\fontsize{16}{22}\selectfont\color{textgray} 1700--1790 baseline};
  \end{tikzpicture}\\[2mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{Sclerosponge Sr/Ca-derived SST anomalies relative to 1700--1790 mean. Shaded region represents 1850--1900 "pre-industrial" reference used by IPCC.}}
}

% ══════════════════════════════════════════════════════
% ROW B (rows 11-15): Background + Key Finding + Methods
% ══════════════════════════════════════════════════════

% ── Why Sclerosponges? (Background) ──
\posterbox[bluecard, title={Why Sclerosponges?}]
{name=background, column=1, between=row11 and row15}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Long-lived marine organisms with continuous growth over centuries
    \item Sr/Ca ratios track sea-surface temperature with high fidelity
    \item Annual-resolution records extend to \textasciitilde1700 CE --- well before instrumental era
    \item Caribbean reef sites capture large-scale tropical SST variability
  \end{itemize}\\[4pt]
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \fontsize{28}{36}\selectfont\color{secondary}\textbf{Crucial}: Provides true pre-industrial baseline, unlike instrumental records that begin \textasciitilde1850.
  }}
}

% ── Pre-Industrial Baseline Matters (Key Finding - highlight) ──
\posterbox[highlightcard, title={The Hidden 0.5 \textdegree C}]
{name=keyfinding, column=2, between=row11 and row15}{
  \fontsize{30}{40}\selectfont
  \colorbox{accent!15}{\parbox{0.94\linewidth}{%
    \textbf{IPCC-reported warming}: \textasciitilde1.2\textdegree C above 1850--1900 baseline (as of 2020)
  }}\\[8pt]
  \colorbox{accent!25}{\parbox{0.94\linewidth}{%
    \fontsize{32}{42}\selectfont\bfseries\color{accent}
    \textbf{True total warming}: \textasciitilde1.7\textdegree C above 1700--1790 baseline
  }}\\[8pt]
  \colorbox{accent!35}{\parbox{0.94\linewidth}{%
    \fontsize{34}{44}\selectfont\bfseries\color{accent}
    \textbf{Hidden warming already baked in by 1850--1900: +0.5 \textdegree C}
  }}\\[8pt]
  \vspace{4pt}
  {\fontsize{24}{32}\selectfont\color{textdark}
    The IPCC's 1850--1900 baseline was NOT truly pre-industrial --- it already captured early industrial warming.
  }
}

% ── Data & Methods ──
\posterbox[darkcard, title={Data \& Methods}]
{name=methods, column=3, between=row11 and row15}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Specimens}: Caribbean sclerosponges, 33--91 m depth
    \item \textbf{Measurement}: ICP-OES Sr/Ca analysis
    \item \textbf{Calibration}: r\textsuperscript{2} > 0.9 vs. instrumental SST (1960--present)
    \item \textbf{Validation}: Excellent agreement with HadCRUT5, NOAA ERSSTv5
  \end{itemize}\\[6pt]
  \colorbox{primary!15}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textgray}
    Divergence from instrumental records only appears before \textasciitilde1850 --- precisely where the hidden warming resides.
  }}
}

% ══════════════════════════════════════════════════════
% ROW C (rows 15-19): Policy Implications + Key Takeaways
% ══════════════════════════════════════════════════════

% ── Policy & Climate Target Implications ──
\posterbox[redcard, title={Policy Implications}]
{name=implications, column=1, between=row15 and row19}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Paris Agreement's 1.5\textdegree C target uses 1850--1900 baseline --- not truly pre-industrial
    \item Sclerosponge-informed baseline reduces remaining carbon budget for 1.5\textdegree C to effectively zero
    \item Only \textasciitilde0.3\textdegree C additional warming available before exceeding 2.0\textdegree C (not \textasciitilde0.8\textdegree C)
    \item Urgency of rapid emissions reductions underscored by these findings
  \end{itemize}\\[4pt]
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{accent}\bfseries
    Key message: The 1.5\textdegree C threshold was crossed years earlier than commonly recognized.
  }}
}

% ── Temperature Comparison Table ──
\posterbox[bluecard, title={Temperature Estimates}]
{name=tempcomp, column=2, between=row15 and row19}{
  \centering
  \rowcolors{1}{bluebg}{white}
  \begin{tabular}{|p{0.42\linewidth}|p{0.25\linewidth}|p{0.22\linewidth}|}
    \hline
    \rowcolor{primary!20}
    \fontsize{26}{34}\selectfont\bfseries\color{primary} Baseline & \fontsize{26}{34}\selectfont\bfseries\color{primary} Warming & \fontsize{26}{34}\selectfont\bfseries\color{primary} Source \\
    \hline
    \fontsize{24}{32}\selectfont 1850--1900 (IPCC) & \fontsize{24}{32}\selectfont \textasciitilde1.2\textdegree C & \fontsize{22}{28}\selectfont HadCRUT5 \\
    \hline
    \fontsize{24}{32}\selectfont 1700--1790 (true) & \fontsize{24}{32}\selectfont \textasciitilde1.7\textdegree C & \fontsize{22}{28}\selectfont This study \\
    \hline
    \rowcolor{accent!30}
    \fontsize{26}{34}\selectfont\bfseries\color{accent} Hidden warming & \fontsize{26}{34}\selectfont\bfseries\color{accent} \textasciitilde0.5\textdegree C & \fontsize{22}{28}\selectfont\color{accent} This study \\
    \hline
  \end{tabular}\\[4pt]
  \vspace{2mm}
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{Higher warming relative to true pre-industrial baseline means earlier threshold crossing.}}
}

% ── Key Takeaways ──
\posterbox[darkcard, title={Key Takeaways}]
{name=takeaways, column=3, between=row15 and row19}{
  \fontsize{30}{40}\selectfont
  \begin{enumerate}[itemsep=12pt]
    \item \textbf{300 years} of proxy temperature data back to \textasciitilde1700 CE
    \item \textbf{+0.5\textdegree C} hidden in IPCC's 1850--1900 baseline
    \item \textbf{1.5\textdegree C} threshold already exceeded (vs. true pre-industrial)
    \item \textbf{Urgency}: Carbon budget for Paris targets much smaller than assumed
  \end{enumerate}\\[6pt]
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    {\fontsize{26}{34}\selectfont\bfseries\color{primary} Study: Nature Climate Change (2024)}
  }}
}

% ══════════════════════════════════════════════════════
% FOOTER (row 20): References
% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=4pt, bottom=4pt,
  halign=left, valign=center,
  borderline north={1pt}{0pt}{primary!30}
]{name=references, column=1, span=3, between=row19 and bottom}{
  \fontsize{22}{28}\selectfont\color{textgray}
  \textbf{References}: Goodkin et al. (2024). Sclerosponge thermometry and global warming exceedance of 1.5\textdegree C. \textit{Nature Climate Change}. |
  Data: Caribbean sclerosponge Sr/Ca records (1700--2020). |
  Validation: HadCRUT5, NOAA ERSSTv5.
}

\end{tcbposter}
\end{document}

