    % "True pre-industrial baseline" arrow
    \draw[primary, <->] (0.02,0.35) -- (0.13,0.35);
    \node at (0.075,0.28) {\fontsize{16}{22}\selectfont\color{textgray} 1700--1790 baseline};
  \end{tikzpicture}\\[2mm]
