    \item \textbf{Calibration}: r\textsuperscript{2} > 0.9 vs. instrumental SST
    \item \textbf{Validation}: Excellent agreement with HadCRUT5, NOAA ERSSTv5
  \end{itemize}\\[6pt]
  \colorbox{primary!15}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textgray}
    Divergence from instrumental records appears only before \textasciitilde1850.
  }}
}

% ── ROW C (rows 15-19) ──
\posterbox[redcard, title={Policy Implications}]
{name=implications, column=1, between=row15 and row19}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Paris Agreement's 1.5\textdegree C target uses 1850--1900 baseline
    \item Sclerosponge baseline reduces carbon budget for 1.5\textdegree C to zero
    \item Only \textasciitilde0.3\textdegree C before exceeding 2.0\textdegree C (not \textasciitilde0.8\textdegree C)
    \item Urgency of rapid emissions reductions underscored
  \end{itemize}\\[4pt]
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{accent}\bfseries
    Key message: 1.5\textdegree C threshold crossed years earlier than recognized.
  }}
}

\posterbox[bluecard, title={Temperature Estimates}]
{name=tempcomp, column=2, between=row15 and row19}{
  \centering
  \rowcolors{1}{bluebg}{white}
  \begin{tabular}{|p{0.42\linewidth}|p{0.25\linewidth}|p{0.22\linewidth}|}
    \hline
    \rowcolor{primary!20}
    \fontsize{26}{34}\selectfont\bfseries\color{primary} Baseline & \fontsize{26}{34}\selectfont\bfseries\color{primary} Warming & \fontsize{26}{34}\selectfont\bfseries\color{primary} Source \\
    \hline
    \fontsize{24}{32}\selectfont 1850--1900 (IPCC) & \fontsize{24}{32}\selectfont \textasciitilde1.2\textdegree C & \fontsize{22}{28}\selectfont HadCRUT5 \\
    \hline
    \fontsize{24}{32}\selectfont 1700--1790 (true) & \fontsize{24}{32}\selectfont \textasciitilde1.7\textdegree C & \fontsize{22}{28}\selectfont This study \\
    \hline
    \rowcolor{accent!30}
    \fontsize{26}{34}\selectfont\bfseries\color{accent} Hidden warming & \fontsize{26}{34}\selectfont\bfseries\color{accent} \textasciitilde0.5\textdegree C & \fontsize{22}{28}\selectfont\color{accent} This study \\
    \hline
  \end{tabular}\\[4pt]
  \vspace{2mm}
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{Higher warming relative to true pre-industrial baseline means earlier threshold crossing.}}
}

\posterbox[darkcard, title={Key Takeaways}]
{name=takeaways, column=3, between=row15 and row19}{
  \fontsize{30}{40}\selectfont
  \begin{enumerate}[itemsep=12pt]
    \item \textbf{300 years} of proxy temperature data back to \textasciitilde1700 CE
    \item \textbf{+0.5\textdegree C} hidden in IPCC's 1850--1900 baseline
    \item \textbf{1.5\textdegree C} threshold already exceeded
    \item \textbf{Urgency}: Carbon budget for Paris targets much smaller
  \end{enumerate}\\[6pt]
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    {\fontsize{26}{34}\selectfont\bfseries\color{primary} Study: Nature Climate Change (2024)}
  }}
}

